import numpy as np
from scipy.optimize import minimize
t,x,v,y=df['t'].values,df['x'].values,df['v'].values,df['dv_dt'].values
tot=np.sum((y-y.mean())**2)
G={'1':np.ones_like(x),'x':x,'x2':x**2,'1/x':1/x,'sqrtx':np.sqrt(x),'expx':np.exp(-x),'sinx':np.sin(x),'cosx':np.cos(x),'logx':np.log(x),'t':t,'t2':t**2,'sint':np.sin(t),'cost':np.cos(t),'expt':np.exp(-t),'1/t':1/t,'logt':np.log(t),'sqrtt':np.sqrt(t),'xt':x*t,'v':v,'sqrtv':np.sqrt(v),'v2':v**2}
out=[]
for gname,g in G.items():
  for form in ['logv','log(a+v)','v^a','exp(-a v)']:
    def f(a):
        if form=='logv': return np.log(v)
        if form=='log(a+v)': return np.log(np.abs(a)+v)
        if form=='v^a': return v**a
        if form=='exp(-a v)': return np.exp(-a*v)
    def obj(p):
        h=f(p[1])*g
        if not np.all(np.isfinite(h)): return 1e3
        A=np.column_stack([t**2,np.sin(p[0]*t)*np.sqrt(v),h,np.ones_like(t)])
        s=np.linalg.lstsq(A,y,rcond=None)[0]
        return np.sum((y-A@s)**2)/tot
    best=None
    for a0 in ([0.1,0.5,1.5] if form!='logv' else [0]):
        for om0 in [0.56,0.62]:
            r=minimize(obj,[om0,a0],method='Nelder-Mead',options={'xatol':1e-10,'fatol':1e-15,'maxiter':3000})
            if best is None or r.fun<best.fun: best=r
    out.append((best.fun,gname,form,best.x))
out.sort(key=lambda z:z[0])
for o in out[:8]: print(o)

